#include <bits/stdc++.h>
using namespace std;
// all values reachable from y by changing at most one digit (first digit != 0), within [1000,2011]
vector<int> cands(int y){
    string s = to_string(y); vector<int> r;
    for(int p=0;p<4;p++) for(char d='0';d<='9';d++){
        if(p==0 && d=='0') continue;
        string t=s; t[p]=d; int v=stoi(t);
        if(v>=1000 && v<=2011) r.push_back(v);
    }
    return r;
}
int main(){
    int n; cin>>n;
    vector<int> y(n), z(n);
    for(auto &x:y) cin>>x;
    int bound=2011;
    for(int i=n-1;i>=0;i--){          // greedy from the right: take the largest value not above the next one
        int best=-1;
        for(int v:cands(y[i])) if(v<=bound) best=max(best,v);
        if(best<0){ cout<<"No solution\n"; return 0; }
        z[i]=best; bound=best;
    }
    for(int v:z) cout<<v<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    ll n,k,s,t; cin>>n>>k>>s>>t;
    vector<ll> c(n), v(n);
    for(int i=0;i<n;i++) cin>>c[i]>>v[i];
    vector<ll> g(k); for(auto &x:g) cin>>x;
    g.push_back(0); g.push_back(s); sort(g.begin(), g.end());
    vector<ll> L;                               // gap lengths between consecutive refuel points
    for(size_t i=1;i<g.size();i++) L.push_back(g[i]-g[i-1]);
    sort(L.begin(), L.end());
    int m=L.size();
    vector<ll> pre(m+1,0);
    for(int i=0;i<m;i++) pre[i+1]=pre[i]+L[i];
    ll best=-1;
    for(int i=0;i<n;i++){
        ll V=v[i];
        if(L[m-1]>V) continue;                  // some gap cannot be crossed on one tank
        int a=upper_bound(L.begin(), L.end(), V/2)-L.begin();  // gaps with 2L<=V: time L
        int b=upper_bound(L.begin(), L.end(), V)-L.begin();    // gaps with V<2L and L<=V: time 3L-V
        ll tm=pre[a] + 3*(pre[b]-pre[a]) - (ll)(b-a)*V;
        if(tm<=t && (best<0 || c[i]<best)) best=c[i];
    }
    cout<<best<<"\n";
}

