// can all exams be passed within the first D days?
bool ok(int D){
    vector<int> last(m+1,0);
    for(int j=1;j<=D;j++) if(d[j]) last[d[j]]=j;   // latest usable exam day for each subject
    vector<long long> need(D+1,0); vector<char> isE(D+1,0);
    for(int i=1;i<=m;i++){
        if(!last[i]) return false;
        isE[last[i]]=1; need[last[i]]+=a[i];
    }
    long long cum=0; int freeCnt=0;
    for(int j=1;j<=D;j++){
        if(!isE[j]) freeCnt++;                  // a non-exam day can be used for preparation
        else { cum+=need[j]; if(cum>freeCnt) return false; }
    }
    return true;
}
