#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m; long long k; cin>>n>>m>>k;
    vector<string> g(n); for(auto &s:g) cin>>s;
    int sx=-1, sy=-1;
    for(int i=0;i<n;i++) for(int j=0;j<m;j++) if(g[i][j]=='X'){ sx=i; sy=j; }
    if(k%2){ cout<<"IMPOSSIBLE\n"; return 0; }              // a closed walk on a grid has even length
    vector<vector<int>> d(n, vector<int>(m,-1));             // BFS distance from the start
    queue<pair<int,int>> q; d[sx][sy]=0; q.push({sx,sy});
    int dx[4]={1,0,0,-1}, dy[4]={0,-1,1,0}; const char dc[4]={'D','L','R','U'};   // lexicographic order
    while(!q.empty()){
        auto [x,y]=q.front(); q.pop();
        for(int t=0;t<4;t++){
            int nx=x+dx[t], ny=y+dy[t];
            if(nx<0||ny<0||nx>=n||ny>=m||g[nx][ny]=='*'||d[nx][ny]>=0) continue;
            d[nx][ny]=d[x][y]+1; q.push({nx,ny});
        }
    }
    string res; int cx=sx, cy=sy;
    for(long long r=k; r>0; r--){                            // r = steps still to make
        bool moved=false;
        for(int t=0;t<4 && !moved;t++){
            int nx=cx+dx[t], ny=cy+dy[t];
            if(nx<0||ny<0||nx>=n||ny>=m||g[nx][ny]=='*') continue;
            if(d[nx][ny]<0 || d[nx][ny]>r-1) continue;      // must still be able to return within r-1 steps
            res+=dc[t]; cx=nx; cy=ny; moved=true;
        }
        if(!moved){ cout<<"IMPOSSIBLE\n"; return 0; }
    }
    cout<<res<<"\n";
}

