int main(){
    int n,m; cin>>n>>m;
    vector<vector<int>> g(n, vector<int>(m));
    for(auto &r:g) for(auto &x:r) cin>>x;
    // every solution has g(i,j) = R_i + C_j; with s = C_0 we get R_i = g(i,0)-s, C_j = g(0,j)-g(0,0)+s
    int lo=0, hi=INT_MAX;
    for(int j=0;j<m;j++) lo=max(lo, g[0][0]-g[0][j]);   // C_j >= 0
    for(int i=0;i<n;i++) hi=min(hi, g[i][0]);           // R_i >= 0
    if(lo>hi){ cout<<-1<<"\n"; return 0; }
    int s = (m>n) ? lo : hi;                            // total = const + (m-n)*s
    vector<int> R(n), C(m);
    for(int i=0;i<n;i++) R[i]=g[i][0]-s;
    for(int j=0;j<m;j++) C[j]=g[0][j]-g[0][0]+s;
    for(int i=0;i<n;i++) for(int j=0;j<m;j++) if(R[i]+C[j]!=g[i][j]){ cout<<-1<<"\n"; return 0; }
    vector<string> ops;
    for(int i=0;i<n;i++) for(int t=0;t<R[i];t++) ops.push_back("row "+to_string(i+1));
    for(int j=0;j<m;j++) for(int t=0;t<C[j];t++) ops.push_back("col "+to_string(j+1));
    cout<<ops.size()<<"\n";
    for(auto &o:ops) cout<<o<<"\n";
}

