    vector<int> lab(n, a>b ? 1 : 2), cnt(6,0), take(6,0);
    for(int x:t) cnt[x]++;
    if(a==b){ fill(lab.begin(), lab.begin()+a, 1); }   // every labelling is optimal; the smallest puts 1s first
    else {
        // a<b: subject 1 must get the top-a multiset; a>b: subject 2 gets the top-b multiset
