        if(a<b) for(int i=0;i<n;i++){ if(take[t[i]]){ lab[i]=1; take[t[i]]--; } }          // earliest copies get 1
        else    for(int i=n-1;i>=0;i--){ if(take[t[i]]){ lab[i]=2; take[t[i]]--; } }       // latest copies get 2
    }
    for(int i=0;i<n;i++) cout<<lab[i]<<(i+1<n?" ":"\n");
}

