const int MX = 2000010;
int nxt[MX+2];
int findp(int x){ while(nxt[x]!=x){ nxt[x]=nxt[nxt[x]]; x=nxt[x]; } return x; }
static char buf[1000005];
int main(){
    int n; scanf("%d",&n);
    for(int i=0;i<=MX+1;i++) nxt[i]=i;               // DSU: next still-unknown cell
    string s(MX,'?'); int len=0;
