            len=max(len, st+L);
            for(int p=findp(st); p<st+L; p=findp(p)){ s[p]=buf[p-st]; nxt[p]=p+1; }
        }
    }
    for(int i=0;i<len;i++) if(s[i]=='?') s[i]='a';   // unknown cells: 'a' gives the lexicographically smallest string
