typedef long long ll;
int main(){
    int n; cin>>n;
    ll w[10]={0}; bool lead[10]={false};
    for(int i=0;i<n;i++){
        string s; cin>>s;
        lead[s[0]-'a']=true;
        ll p=1;
        for(int j=(int)s.size()-1;j>=0;j--){ w[s[j]-'a']+=p; p*=10; }   // weight = sum of place values
    }
    ll best=LLONG_MAX;
    for(int z=0;z<10;z++){                       // letter that gets digit 0 must not lead a number
