        vector<ll> rest;
        for(int c=0;c<10;c++) if(c!=z) rest.push_back(w[c]);
        sort(rest.rbegin(), rest.rend());        // heaviest letter gets the smallest digit
        ll tot=0;
        for(int i=0;i<9;i++) tot+=rest[i]*(i+1);
        best=min(best,tot);
    }
    cout<<best<<"\n";
}

