int main(){
    long long X,d; cin>>X>>d;
    vector<int> cs;                              // X = sum over clusters of (2^c - 1)
    while(X>0){
        int c=1;
        while((1LL<<(c+1))-1 <= X) c++;          // largest c with 2^c - 1 <= X
        cs.push_back(c);
        X -= (1LL<<c)-1;
    }
    // cluster i has c_i copies of value i*d; values in different clusters differ by >= d, so they never combine
    vector<long long> a;
    for(size_t i=0;i<cs.size();i++) for(int j=0;j<cs[i];j++) a.push_back((long long)(i+1)*d);
    printf("%d\n",(int)a.size());
    for(auto v:a) printf("%lld ",v);
    printf("\n");
}

