#include <bits/stdc++.h>
using namespace std;
#ifndef N
#define N 256                                   // number of colours (overridable for brute-force tests)
#endif
int K; bool fb[N+1], fr[N+1], F[N+1], G[N+1]; int pre[N+2];
// cut positions 0..N; fr = forced cut, fb = forbidden cut; F/G = prefix/suffix feasibility
void calc(){
    pre[0]=0; for(int p=0;p<=N;p++) pre[p+1]=pre[p]+fr[p];   // pre[x] = forced cuts in [0,x)
    for(int p=0;p<=N;p++){
        F[p]=false; if(fb[p]) continue;
        if(p==0){ F[p]=true; continue; }
        for(int j=max(0,p-K); j<p; j++) if(F[j] && pre[p]-pre[j+1]==0){ F[p]=true; break; }
    }
    for(int p=N;p>=0;p--){
        G[p]=false; if(fb[p]) continue;
        if(p==N){ G[p]=true; continue; }
        for(int e=p+1; e<=min(N,p+K); e++) if(G[e] && pre[e]-pre[p+1]==0){ G[p]=true; break; }
    }
}
int main(){
    int n; cin>>n>>K;
    vector<int> p(n); for(auto &x:p) cin>>x;
    fr[0]=fr[N]=true;
    vector<int> key(N,0), order; vector<bool> seen(N,false);
    for(int x:p) if(!seen[x]){ seen[x]=true; order.push_back(x); }
    for(int c:order){                            // colours in first-occurrence order; give each the smallest feasible group start
        calc();
        for(int s=max(0,c-K+1); s<=c; s++){
            if(!F[s] || fb[s]) continue;
            bool ok=false;
            for(int e=c+1; e<=min(N,s+K) && !ok; e++) if(G[e] && pre[e]-pre[s+1]==0) ok=true;
            if(!ok) continue;
            key[c]=s; fr[s]=true;
            for(int q=s+1;q<=c;q++) fb[q]=true;  // c's group starts at s, so no cut in (s, c]
            break;
        }
    }
    for(int i=0;i<n;i++) cout<<key[p[i]]<<(i+1<n?" ":"\n");
}

