#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n; ll M; cin>>n>>M;
    vector<ll> P(n+2); P[0]=0;
    for(int i=1;i<=n;i++) cin>>P[i];
    P[n+1]=M;
    int S=n+1;                                  // segments j = [P[j], P[j+1]); lamp is on for even j
    vector<ll> lit(S,0), suf(S+1,0);
    ll L0=0;
    for(int j=0;j<S;j++){ lit[j]=(j%2==0)?P[j+1]-P[j]:0; L0+=lit[j]; }
    for(int j=S-1;j>=0;j--) suf[j]=suf[j+1]+lit[j];
    ll best=L0;                                 // inserting nothing is allowed
    for(int j=0;j<S;j++){
        if(P[j+1]-P[j]<2) continue;             // no integer strictly inside this gap
        bool on=(j%2==0);
        for(ll x: {P[j]+1, P[j+1]-1}){          // the value is linear in x inside a gap, so the ends suffice
            ll Lx=(on?P[j+1]-x:0)+suf[j+1];     // lit time in [x, M)
            best=max(best, L0-2*Lx+(M-x));      // flipping [x, M) gives this total
        }
    }
    cout<<best<<"\n";
}

