#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n; cin>>n;
    vector<pair<long long,int>> f;              // prime factorisation of n
    long long m=n;
    for(long long p=2;p*p<=m;p++) if(m%p==0){ int e=0; while(m%p==0){ m/=p; e++; } f.push_back({p,e}); }
    if(m>1) f.push_back({m,1});
    long long bestV=-1, bestOps=0;
    for(int t=0;t<=21;t++){                     // t square roots at the end; exponents become ceil(e / 2^t)
        long long k=1LL<<t, V=1; bool need=false;
        for(auto [p,e]: f){
            long long c=(e+k-1)/k;
            for(long long j=0;j<c;j++) V*=p;
            if(e%k) need=true;                  // one 'mul' by a suitable x makes all exponents multiples of 2^t
        }
        long long ops=t+(need?1:0);
        if(bestV<0 || V<bestV || (V==bestV && ops<bestOps)){ bestV=V; bestOps=ops; }
    }
    cout<<bestV<<" "<<bestOps<<"\n";
}

