#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// types: A = "11", B = "10", C = "01", D = "00"; each sorted descending, with prefix sums.
// Choose p,q,r,s from A,B,C,D. Conditions: p+q >= r+s and p+r >= q+s, i.e. |q-r| <= d where d = p-s >= 0.
int main(){
    int n; cin>>n;
    vector<ll> v[4];
    for(int i=0;i<n;i++){ string s; ll a; cin>>s>>a; v[(s[0]-'0')*2+(s[1]-'0')].push_back(a); }
    vector<ll> A=v[3], B=v[2], C=v[1], D=v[0];           // "11"=3, "10"=2, "01"=1, "00"=0
    for(auto *x: {&A,&B,&C,&D}) sort(x->rbegin(), x->rend());
    auto pref=[](const vector<ll>& x){ vector<ll> p(x.size()+1,0); for(size_t i=0;i<x.size();i++) p[i+1]=p[i]+x[i]; return p; };
    vector<ll> PA=pref(A), PB=pref(B), PC=pref(C), PD=pref(D);
    int nA=A.size(), nB=B.size(), nC=C.size(), nD=D.size();
    // W(e): best PB[q]+PC[r] with q-r=e; positive values mean the largest feasible r is optimal
    const ll NEG=LLONG_MIN/4;
    vector<ll> W(nB+nC+1, NEG);                        // index e+nC for e in [-nC, nB]
    for(int e=-nC; e<=nB; e++){
        int rlo=max(0,-e), rhi=min(nC, nB-e);
        if(rlo>rhi) continue;
        W[e+nC]=PB[rhi+e]+PC[rhi];
    }
    vector<ll> G(nA+1, NEG);                           // G[d] = best over |e| <= d
    for(int d=0; d<=nA; d++){
        ll best = (d==0)? 0 : G[d-1];
        if(d<=nB && W[d+nC]>best) best=W[d+nC];       // W(d): valid when d <= nB
        if(d<=nC && W[-d+nC]>best) best=W[-d+nC];     // W(-d): valid when d <= nC
        G[d]=best;
    }
    ll ans=0;
    for(int d=0; d<=nA; d++){
        int s=min(nD, nA-d);                           // take as many 00 as allowed (values are positive)
        ll H=PA[s+d]+PD[s];
        ans=max(ans, H+G[d]);
    }
    cout<<ans<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; string s; cin>>n>>s;
    int k=n/3, cnt[3]={0,0,0};
    for(char c: s) cnt[c-'0']++;
    // pass 1: an over-used digit becomes a smaller under-used digit when possible (lex-smaller, one change)
    for(int i=0;i<n;i++){
        int c=s[i]-'0';
        if(cnt[c]<=k) continue;
        for(int d=0; d<c; d++) if(cnt[d]<k){ cnt[c]--; cnt[d]++; s[i]='0'+d; break; }
    }
    // pass 2: remaining over-used digits are replaced at their rightmost occurrences,
    // and the needed digits are placed in ascending order from left to right
    vector<int> chg;
    vector<bool> mark(n,false);
    for(int i=n-1;i>=0;i--){
        int c=s[i]-'0';
        if(cnt[c]>k){ cnt[c]--; mark[i]=true; chg.push_back(i); }
    }
    vector<int> need;
    for(int d=0; d<3; d++) for(int t=cnt[d]; t<k; t++) need.push_back(d);
    sort(chg.begin(), chg.end());
    for(size_t j=0;j<chg.size();j++) s[chg[j]]='0'+need[j];
    cout<<s<<"\n";
}

