    vector<pair<int,int>> pr;
    // 1) identical letters first (greedy is optimal for exact matches)
    for(int c=0;c<26;c++)
        while(!li[c].empty() && !ri[c].empty()){ pr.push_back({li[c].back(), ri[c].back()}); li[c].pop_back(); ri[c].pop_back(); }
    // 2) left letters against right '?', 3) right letters against left '?', 4) '?' against '?'
    for(int c=0;c<26;c++){
        while(!li[c].empty() && !rq.empty()){ pr.push_back({li[c].back(), rq.back()}); li[c].pop_back(); rq.pop_back(); }
        while(!ri[c].empty() && !lq.empty()){ pr.push_back({lq.back(), ri[c].back()}); ri[c].pop_back(); lq.pop_back(); }
    }
    while(!lq.empty() && !rq.empty()){ pr.push_back({lq.back(), rq.back()}); lq.pop_back(); rq.pop_back(); }
