        if(s[i]==1){
            if(acc<a && bat>0){ bat--; acc++; }      // sunlit: battery drives and charges the accumulator (if it has room)
            else if(acc>0) acc--;                    // full accumulator: spend it, keep the battery
            else if(bat>0) bat--;
            else break;
        } else {
            if(acc>0) acc--;                      // dark: prefer the accumulator
            else if(bat>0) bat--;
            else break;
        }
        passed++;
    }
    cout<<passed<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int n,m; cin>>n>>m;
    vector<ll> b(n), g(m);
    for(auto &x:b) cin>>x;
    for(auto &x:g) cin>>x;
    ll Bmax=*max_element(b.begin(), b.end());
    ll gmin=*min_element(g.begin(), g.end());
    if(Bmax>gmin){ cout<<-1<<"\n"; return 0; }
    // every gift is at least its boy's minimum, so base = m * b_i for each boy;
    // each girl needs one cell equal to g_j; the cheapest is to take it from the boy with Bmax
    ll base=0; for(ll x:b) base+=(ll)m*x;
    ll tot=base; for(ll x:g) tot+=x-Bmax;
    bool hasEq=false; for(ll x:g) if(x==Bmax) hasEq=true;
    if(!hasEq){
        // the top boy must keep one cell at his minimum, so one girl takes her gift from the second boy
        sort(b.begin(), b.end(), greater<ll>());
        tot += Bmax - b[1];
    }
    cout<<tot<<"\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,m; cin>>n>>m;
    vector<string> g(n); for(auto &s:g) cin>>s;
    vector<int> L(n,-1), R(n,-1);                     // leftmost / rightmost weed column per row
    int last=-1;
    for(int i=0;i<n;i++) for(int j=0;j<m;j++) if(g[i][j]=='W'){
        if(L[i]<0) L[i]=j;
        R[i]=j; last=i;
    }
    if(last<0){ cout<<0<<"\n"; return 0; }
    long long moves=0; int cur=0;
    for(int i=0;i<=last;i++){
        if(i%2==0){                                   // moving right: reach every weed of this row and the next
            int t=cur;
            if(R[i]>=0) t=max(t,R[i]);
            if(i+1<=last && R[i+1]>=0) t=max(t,R[i+1]);
            moves+=t-cur; cur=t;
        } else {                                      // moving left
            int t=cur;
            if(L[i]>=0) t=min(t,L[i]);
            if(i+1<=last && L[i+1]>=0) t=min(t,L[i+1]);
            moves+=cur-t; cur=t;
        }
        if(i<last) moves++;                           // step down (this also reverses direction)
    }
    cout<<moves<<"\n";
}

